#include <windows.h>
#include <stdio.h>
static void check(const char *label){BYTE in[256]={0},out[256]={0};BOOL s,g;in['Z']=0x80;s=SetKeyboardState(in);g=GetKeyboardState(out);printf("%s set=%d get=%d ownZ=%u key=%04x\n",label,s,g,out['Z'],(unsigned short)GetKeyState('Z'));ZeroMemory(in,sizeof(in));SetKeyboardState(in);}
int main(void){MSG m;BYTE x[256];HWND w;char path[MAX_PATH];PeekMessage(&m,NULL,0,0,PM_NOREMOVE);GetModuleFileNameA(GetModuleHandleA("user32.dll"),path,MAX_PATH);printf("user32=%s\n",path);check("initial");GetKeyboardState(x);check("primed");w=CreateWindowExA(0,"STATIC","owned-unshown-control",WS_POPUP,0,0,1,1,NULL,NULL,GetModuleHandle(NULL),NULL);printf("window=%d\n",w!=NULL);check("unshown-window");if(w)DestroyWindow(w);return 0;}
